#!/usr/bin/env python3
import csv
import json
import sys


def is_number(value):
    try:
        float(value)
        return True
    except ValueError:
        return False


def main(argv):
    if len(argv) != 2:
        print("usage: stats.py <chemin.csv>", file=sys.stderr)
        return 2

    try:
        with open(argv[1], newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                print("{}")
                return 0
            columns = {name: [] for name in header}
            for row in reader:
                for i, name in enumerate(header):
                    if i < len(row):
                        raw = row[i].strip()
                        if raw:
                            columns[name].append(raw)
    except OSError as e:
        print(f"erreur: {e}", file=sys.stderr)
        return 1
    except (csv.Error, UnicodeDecodeError) as e:
        print(f"erreur: {e}", file=sys.stderr)
        return 1

    result = {}
    for name, values in columns.items():
        if not values:
            continue
        if not all(is_number(v) for v in values):
            continue
        nums = [float(v) for v in values]
        result[name] = {
            "count": len(nums),
            "mean": sum(nums) / len(nums),
            "min": min(nums),
            "max": max(nums),
        }

    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

